from collections import deque

def depot_shares(grid):
    rows, cols = len(grid), len(grid[0])

    def spread(mark):
        dist = [[-1] * cols for _ in range(rows)]
        queue = deque()
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == mark:
                    dist[i][j] = 0
                    queue.append((i, j))
        while queue:
            i, j = queue.popleft()
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= a < rows and 0 <= b < cols and dist[a][b] < 0 and grid[a][b] != '#':
                    dist[a][b] = dist[i][j] + 1
                    queue.append((a, b))
        return dist

    da, db = spread('A'), spread('B')
    a_cells = b_cells = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != '.':
                continue
            x, y = da[i][j], db[i][j]
            if x >= 0 and (y < 0 or x < y):
                a_cells += 1
            elif y >= 0 and (x < 0 or y < x):
                b_cells += 1
    return [a_cells, b_cells]

