from collections import deque

def depot_shares(grid):
    rows, cols = len(grid), len(grid[0])
    near = {'A': [[-1] * cols for _ in range(rows)], 'B': [[-1] * cols for _ in range(rows)]}
    for si in range(rows):
        for sj in range(cols):
            mark = grid[si][sj]
            if mark not in 'AB':
                continue
            best = near[mark]
            dist = {(si, sj): 0}
            queue = deque([(si, sj)])
            while queue:
                i, j = queue.popleft()
                d = dist[(i, j)]
                if best[i][j] < 0 or d < best[i][j]:
                    best[i][j] = d
                for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                    if 0 <= a < rows and 0 <= b < cols and (a, b) not in dist and grid[a][b] != '#':
                        dist[(a, b)] = d + 1
                        queue.append((a, b))
    out = [0, 0]
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '.':
                x, y = near['A'][i][j], near['B'][i][j]
                if x >= 0 and (y < 0 or x < y):
                    out[0] += 1
                elif y >= 0 and (x < 0 or y < x):
                    out[1] += 1
    return out
